members.scene_root:
使用该行为树的场景的根节点（例如，[BTPlayer] 节点的拥有者）。可用于获取 [NodePath] 引用。
[b]示例：[/b]
[codeblock]
extends BTAction

@export var node_path: NodePath

func _setup():
    var node: Node = scene_root.get_node(node_path)
[/codeblock]

methods.add_transition:
当派发 [param event] 时，建立从某个状态到另一个状态的过渡。[param from_state] 和 [param to_state] 都必须是此 [LimboHSM] 的直接子节点。
可以选择性地指定 [param guard] 函数，该函数必须返回布尔值。如果守卫函数返回 [code]false[/code]，则过渡不会发生。守卫函数会在考虑过渡之前立即被调用。对于状态级别的守卫函数，请参阅 [method LimboState.set_guard]。
[codeblock]
func my_guard() -> bool:
    return is_some_condition_met()
[/codeblock]
